                    float3 yuv = baseColor * rgb2yuv;
                    yuv.gb = (yuv.gb-0.5) * 2.0 + 0.5;
                    yuv.r = floor((yuv.r + 0.166667)*3.0)/3.0;
                    matchColor = float3(yuv * yuv2rgb);
                } else if( int(amzp_palette) == 11 ) {
                    matchColor = amzp_color1.rgb;
                } else if( int(amzp_palette) == 12 ) {
                    float d1 = colorDiff(baseColor,amzp_color1.rgb);
                    float d2 = colorDiff(baseColor,amzp_color2.rgb);
                    float dmin = min(d1,d2);
                    matchColor = dmin==d1 ? amzp_color1.rgb : amzp_color2.rgb;
                } else if( int(amzp_palette) == 13 ) {
                    float d1 = colorDiff(baseColor,amzp_color1.rgb);
                    float d2 = colorDiff(baseColor,amzp_color2.rgb);
                    float d3 = colorDiff(baseColor,amzp_color3.rgb);
                    float dmin = min(min(d1,d2),d3);
                    matchColor =
                        dmin==d1 ? amzp_color1.rgb :
                        dmin==d2 ? amzp_color2.rgb :
                        amzp_color3.rgb;
                } else if( int(amzp_palette) == 14 ) {
                    float d1 = colorDiff(baseColor,amzp_color1.rgb);
                    float d2 = colorDiff(baseColor,amzp_color2.rgb);
                    float d3 = colorDiff(baseColor,amzp_color3.rgb);
                    float d4 = colorDiff(baseColor,amzp_color4.rgb);
                    float dmin = min(min(d1,d2),min(d3,d4));
                    matchColor =
                        dmin==d1 ? amzp_color1.rgb :
                        dmin==d2 ? amzp_color2.rgb :
                        dmin==d3 ? amzp_color3.rgb :
                        amzp_color4.rgb;
                } else if( int(amzp_palette) == 15 ) {
                    float d1 = colorDiff(baseColor,amzp_color1.rgb);
                    float d2 = colorDiff(baseColor,amzp_color2.rgb);
                    float d3 = colorDiff(baseColor,amzp_color3.rgb);
                    float d4 = colorDiff(baseColor,amzp_color4.rgb);
                    float d5 = colorDiff(baseColor,amzp_color5.rgb);
                    float dmin = min(min(min(d1,d2),min(d3,d4)),d5);
                    matchColor =
                        dmin==d1 ? amzp_color1.rgb :
                        dmin==d2 ? amzp_color2.rgb :
                        dmin==d3 ? amzp_color3.rgb :
                        dmin==d4 ? amzp_color4.rgb :
                        amzp_color5.rgb;
                } else if( int(amzp_palette) == 16 ) {
                    float d1 = colorDiff(baseColor,amzp_color1.rgb);
                    float d2 = colorDiff(baseColor,amzp_color2.rgb);
                    float d3 = colorDiff(baseColor,amzp_color3.rgb);
                    float d4 = colorDiff(baseColor,amzp_color4.rgb);
                    float d5 = colorDiff(baseColor,amzp_color5.rgb);
                    float d6 = colorDiff(baseColor,amzp_color6.rgb);
                    float dmin = min(min(min(d1,d2),min(d3,d4)),min(d5,d6));
                    matchColor =
                        dmin==d1 ? amzp_color1.rgb :
                        dmin==d2 ? amzp_color2.rgb :
                        dmin==d3 ? amzp_color3.rgb :
                        dmin==d4 ? amzp_color4.rgb :
                        dmin==d5 ? amzp_color5.rgb :
                        amzp_color6.rgb;
                }



                outColor = float4(matchColor,1.)*texColor.a;
                float3 err = baseColor - matchColor;
                accumErr = err * amzp_errorWeight * mix(1.,pct*pct,amzp_errorFalloff);
            }
            float4 origColor = amzTexture(0, amzScreenNorm().st);
            float4 result;
            if( int(amzp_blendMode)==1 ) { 
                float3 a = origColor.rgb / max(origColor.a,0.00001);
                float3 b = outColor.rgb / max(outColor.a,0.00001);
                result = float4(a * b, 1.) * origColor.a;
            } else if( int(amzp_blendMode)==2 ) { 
                float3 a = origColor.rgb / max(origColor.a,0.00001);
                float3 b = outColor.rgb / max(outColor.a,0.00001);
                result = float4(1.-((1.-a) * (1.-b)), 1.) * origColor.a;
            } else {
                result = outColor;
            }
            amzOutput = mix(origColor,result,amzp_alpha);
        }


